3	/// Retiming an action by dragging its band on the timeline (spec §11
4	/// CI-11): the begin/continue/end bodies, the hover, the cursors and the
5	/// ghost with its HUD. `TimelineView.swift` is frozen at wiring
6	/// (app/CLAUDE.md), so it keeps the stored `actionDrag` and `bandHover`, one
7	/// arm per gesture phase, a draw call, a cursor call and three one-line
8	/// overrides; the bodies are here.
9	extension TimelineView {
10	    /// Mouse-down on a band, after the press has selected the clip and the
11	    /// action (the timeline selects at mouse-DOWN). A zero-length action is
12	    /// never dragged — `duration: 0` is invalid input to the core, not a
13	    /// refusal — and neither is one on a locked track.
14	    func beginActionDrag(clip id: UInt32, action: UInt32, mode: ActionDragMode, at point: CGPoint) {
15	        guard let clip = snapshot.clip(id),
16	              let index = snapshot.trackIndex(of: clip.track),
17	              !snapshot.tracks[index].locked,
18	              let found = clip.actions.first(where: { $0.id == action }),
19	              found.duration > 0
20	        else { return }
21	        bandHover = nil
22	        actionDrag = ActionDragSession(
23	            clip: clip, action: found, mode: mode,
24	            grabAt: layout.time(atX: point.x) - clip.start, fps: snapshot.canvas.fps)
25	        onLiveBegin?()
26	    }
27	
28	    /// Mouse-dragged: one `set_action` per tick. A tick the core refuses is
29	    /// swallowed by `updateLiveEdit` (spec §11 CI-10's last sentence).
30	    func continueActionDrag(at point: CGPoint) {
31	        guard var session = actionDrag, let clip = snapshot.clip(session.clip) else { return }
32	        session.update(clipTime: layout.time(atX: point.x) - clip.start)
33	        actionDrag = session
34	        onLiveUpdate?([session.op])
35	    }
36	
37	    /// Mouse-up: the gesture as ONE undo step (none when nothing applied),
38	    /// then — after a real drag — the action selected again, which parks the
39	    /// playhead at its NEW end.
40	    func endActionDrag() {
41	        guard let session = actionDrag else { return }
42	        actionDrag = nil
43	        onLiveEnd?(session.undoName)
44	        if session.didMove { onActionSelected?(session.clip, session.action) }
45	    }
46	}
47	
48	extension TimelineContentView {
49	    /// One area of this view's own for the band hover; only areas it OWNS are
50	    /// removed (app/CLAUDE.md "Tracking areas"), and `.inVisibleRect` means a
51	    /// scroll needs no reinstall.
52	    func installBandTracking() {
53	        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
54	        addTrackingArea(
55	            NSTrackingArea(
56	                rect: .zero,
57	                options: [.mouseMoved, .mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
58	                owner: self, userInfo: nil))
59	    }
60	
61	    /// The band under the pointer, from the one hit test — nil while a drag
62	    /// is live.
63	    func bandHoverMoved(with event: NSEvent) {
64	        guard let owner = timeline else { return }
65	        guard owner.actionDrag == nil else {
66	            owner.bandHover = nil
67	            return
68	        }
69	        switch hit(at: convert(event.locationInWindow, from: nil)) {
70	        case .action(let clip, let action):
71	            owner.bandHover = ActionBandHover(clip: clip, action: action, edge: nil)
72	        case .actionEdge(let clip, let action, let edge):
73	            owner.bandHover = ActionBandHover(clip: clip, action: action, edge: edge)
74	        default:
75	            owner.bandHover = nil
76	        }
77	    }
78	
79	    func bandHoverExited() { timeline?.bandHover = nil }
80	
81	    /// `.openHand` over a band's body and `.resizeLeftRight` over its grips,
82	    /// for the bands a press can drag: unlocked tracks, positive lengths.
83	    func addActionBandCursorRects(owner: TimelineView, layout: TimelineLayout, visible: CGRect) {
84	        for (index, track) in owner.snapshot.tracks.enumerated() where !track.locked {
85	            let row = layout.row(forTrackIndex: index)
86	            for clip in owner.snapshot.clips(onTrack: track.id) {
87	                let rect = layout.clipRect(clip, row: row)
88	                guard rect.intersects(visible) else { continue }
89	                let lane = Self.actionLane(
90	                    content: Self.contentRect(rect), sizeIndex: owner.trackHeightIndex)
91	                guard lane.height > 0 else { continue }
92	                for action in clip.actions where action.duration > 0 {
93	                    addGripCursorRects(
94	                        Self.bandRect(action, clip: clip, lane: lane, layout: layout))
95	                }
96	            }
97	        }
98	    }
99	
100	    /// While a drag has moved: the original band as a dashed ghost, and the
101	    /// HUD at the band's left, 18 pt above the clip, kept inside the lanes
102	    /// and the visible rect.
103	    func drawActionDragOverlay(owner: TimelineView, layout: TimelineLayout) {
104	        guard let session = owner.actionDrag, session.didMove,
105	              let clip = owner.snapshot.clip(session.clip),
106	              let index = owner.snapshot.trackIndex(of: clip.track)
107	        else { return }
108	        let rect = layout.clipRect(clip, row: layout.row(forTrackIndex: index))
109	        let lane = Self.actionLane(
110	            content: Self.contentRect(rect), sizeIndex: owner.trackHeightIndex)
111	        let original = ActionSnapshot(
112	            id: session.action, start: session.originalStart, duration: session.originalDuration)
113	        ActionDragSession.drawGhost(
114	            Self.bandRect(original, clip: clip, lane: lane, layout: layout))
115	        let text = session.hud(base: clip.start, frames: owner.snapshot.canvas.timecodeFrames)
116	        let width = ActionDragSession.hudWidth(text)
117	        let visible = visibleRect
118	        var x = layout.x(for: clip.start + session.start)
119	        x = min(max(x, visible.minX + TimelineLayout.headerWidth), visible.maxX - width)
120	        var y = max(rect.minY - 18, visible.minY + layout.lanesTop)
121	        y = min(y, visible.maxY - ActionDragSession.hudHeight)
122	        ActionDragSession.drawHUD(text, at: CGPoint(x: x, y: y))
123	    }
124	}
