111	extension Curve {
112	    /// The lane's Curve popup titles, "Ease " dropped (spec §11 CI-12);
113	    /// `displayName` stays the spelling everywhere else.
114	    var laneName: String {
115	        switch self {
116	        case .linear: return "Linear"
117	        case .easeIn: return "In"
118	        case .easeOut: return "Out"
119	        case .easeInOut: return "In Out"
120	        }
121	    }
122	}
123	
124	/// The 16 × 10 curve glyph before the lane's Curve popup: the band's own
125	/// `ActionBands.curvePath`, 1.25 pt in `DS.action`. Beside the popup rather
126	/// than inside it, because `OptionPopupControl` is Rasterize's and is not
127	/// forked (CI-12).
128	final class CurveGlyphView: NSView, OptionControl {
129	    private let read: () -> Curve
130	    private var shown: Curve?
131	
132	    init(read: @escaping () -> Curve) {
133	        self.read = read
134	        super.init(frame: NSRect(x: 0, y: 0, width: 16, height: 10))
135	        translatesAutoresizingMaskIntoConstraints = false
136	        NSLayoutConstraint.activate([
137	            widthAnchor.constraint(equalToConstant: 16),
138	            heightAnchor.constraint(equalToConstant: 10),
139	        ])
140	        refresh()
141	    }
142	
143	    @available(*, unavailable)
144	    required init?(coder: NSCoder) {
145	        fatalError("CurveGlyphView does not support NSCoder")
146	    }
147	
148	    override var isFlipped: Bool { true }
149	
150	    func refresh() {
151	        let curve = read()
152	        guard curve != shown else { return }
153	        shown = curve
154	        needsDisplay = true
155	    }
156	
157	    override func draw(_ dirtyRect: NSRect) {
158	        let path = ActionBands.curvePath(read(), in: bounds.insetBy(dx: 0.75, dy: 0.75))
159	        path.lineWidth = 1.25
160	        DS.action.setStroke()
161	        path.stroke()
162	    }
163	}
164

150	            mark = next
151	            needsDisplay = true
152	        }
153	        let ink = isKeyed ? DS.textStrong : mark == .notAnimatable ? DS.textFaint : DS.textMuted
154	        if let label, label.textColor != ink { label.textColor = ink }
155	        updateToolTip()
156	        paintBorders()
157	    }
158	
159	    private func updateToolTip() {
160	        if showsRemove, let number = binding?.selectedActionNumber {
161	            toolTip = "Remove from action \(number)"
162	        } else if case .other(let number) = mark {
163	            toolTip = "Changed by action \(number)"
164	        } else {
165	            toolTip = nil
166	        }
167	    }
168	
169	    /// The keyed rows' 1 pt action-ink border on their fields and popups.
170	    private func paintBorders() {
171	        let keyed = isKeyed
172	        for control in controls where control is OptionFieldControl
173	            || control is OptionPopupControl
174	        {
175	            if keyed { control.wantsLayer = true }
176	            guard let layer = control.layer else { continue }
177	            layer.borderWidth = keyed ? 1 : 0
178	            if keyed {
179	                effectiveAppearance.performAsCurrentDrawingAppearance {
180	                    layer.borderColor = DS.action.cgColor
181	                }
182	            }
183	        }
184	    }
185	
186	    /// A `CGColor` does not follow the appearance, so the border is resolved
187	    /// again when it changes.
188	    override func viewDidChangeEffectiveAppearance() {
189	        super.viewDidChangeEffectiveAppearance()
190	        paintBorders()
191	    }
192	
193	    override func mouseDown(with event: NSEvent) {
194	        guard showsRemove else {
195	            super.mouseDown(with: event)
196	            return
197	        }
198	        removeFromAction()
199	    }
